#include "th10/game/projectile_command_runtime.hpp"
namespace th10::projectile_commands {
// Semantic reconstruction of retail 0x00406D90: command stream execution for one spawned projectile.
void Apply(State&s,const std::vector<Command>&v,const Edges&e){while(s.cursor<(int)v.size()&&s.cursor<18){const auto&c=v[s.cursor];if(c.opcode==0||c.opcode==0x80000000){++s.cursor;if(c.opcode==0)return;continue;}switch(c.opcode){case 1:s.flags|=1;s.sound=0;break;case 0x10:s.flags|=0x10;s.speed=c.a[0];s.angle=c.a[1];s.accel=c.a[2];break;case 0x20:s.flags|=0x20;s.speed=c.a[0];s.target_speed=c.a[1];s.accel=c.a[2];break;case 0x40:case 0x80:case 0x100:s.flags|=c.opcode;s.angle=c.a[0];s.speed=c.a[1];s.duration=c.a[2];break;case 0x400:case 0x800:case 0x8000000:s.flags|=c.opcode;s.scale=c.a[0];s.duration=c.a[2];break;case 0x1000:s.spawn_x=c.a[2];break;case 0x2000:s.spawn_y=c.a[2];break;case 0x8000:case 0x100000:case 0x200000:s.flags|=c.opcode;s.sound=(int)c.a[2];break;case 0x4000:case 0x10000:case 0x20000:if(e.event)e.event(e.context,c.opcode,c);break;case 0x400000:s.spawn_x=c.a[0];s.spawn_y=c.a[1];s.spawn_z=c.a[2];++s.spawn_count;if(e.event)e.event(e.context,c.opcode,c);break;case 0x1000000:s.spawn_z=c.a[2];break;case 0x2000000:s.cursor=(int)c.a[2];continue;case 0x4000000:s.flags|=c.opcode;s.speed=c.a[0];s.target_speed=c.a[1];s.duration=c.a[2];break;default:if(e.event)e.event(e.context,c.opcode,c);break;}++s.cursor;}}
}
